__d(function(a,e,i,t,n,s,r){n.exports={version:"2.0",board:"Karnataka State Board / NCERT",grade:6,subject:"English",textbook:"A Pact with the Sun",chapter_number:5,chapter_title:"Tansen",total_cards:20,cards:[{id:"fc01",type:"Recall",difficulty:"Easy",front:"What was Tansen's real name?",back:"Ramtanu. He was later given the name 'Tansen' \u2014 which means 'master of musical notes.'",memory_hook:"Tansen = Tan (notes) + Sen (master). His name describes who he became."},{id:"fc02",type:"Recall",difficulty:"Easy",front:"Where and approximately when was Tansen born?",back:"Tansen was born in Gwalior (in present-day Madhya Pradesh) around 1506.",memory_hook:"Gwalior = city of music. Tansen's birthplace is famous for its musical heritage."},{id:"fc03",type:"Recall",difficulty:"Easy",front:"What was Tansen like as a child?",back:"He was a mischievous, wild boy who loved roaming the forest. He had an extraordinary ability to imitate the sounds of birds and animals.",memory_hook:"Wild boy in forest \u2192 imitating animals \u2192 discovered by great guru. Talent found in the most unexpected place!"},{id:"fc04",type:"Recall",difficulty:"Easy",front:"Who discovered Tansen's musical talent?",back:"Swami Haridas \u2014 a great musician and saint \u2014 heard the boy imitating animals in the forest and recognised his extraordinary talent.",memory_hook:"Right place + right time + right ears = Swami Haridas + young Tansen."},{id:"fc05",type:"Recall",difficulty:"Easy",front:"How long did Tansen train under Swami Haridas?",back:"Eleven years. This long, dedicated period of training transformed his raw talent into true mastery.",memory_hook:"11 years = not months, not one year. ELEVEN. Mastery takes time. No shortcuts."},{id:"fc06",type:"Recall",difficulty:"Easy",front:"Who was Tansen's second guru?",back:"Muhammad Ghaus \u2014 a Sufi saint and musician at Gwalior, under whom Tansen continued his training after studying with Swami Haridas.",memory_hook:"Two gurus = two layers of learning. Swami Haridas (classical) + Muhammad Ghaus (spiritual)."},{id:"fc07",type:"Recall",difficulty:"Easy",front:"Which Mughal emperor invited Tansen to his court?",back:"Emperor Akbar \u2014 one of the greatest Mughal emperors, known for his love of arts, music, and culture.",memory_hook:"Akbar = art lover. Tansen = gem. Akbar collected gems \u2014 the Navaratnas!"},{id:"fc08",type:"Definition",difficulty:"Easy",front:"What are the 'Navaratnas'?",back:"The Navaratnas (Nine Gems) were the nine most talented and brilliant people at Emperor Akbar's court. Tansen was one of them \u2014 the musical gem.",memory_hook:"Nava = 9. Ratna = gem. Tansen = the musical jewel in Akbar's crown."},{id:"fc09",type:"Definition",difficulty:"Easy",front:"What is a 'raga' in Indian classical music?",back:"A raga is a pattern or framework of musical notes in Indian classical music. Each raga has its own mood, rules, and is associated with a specific time, season, or emotion.",memory_hook:"Raga = framework of notes + specific mood. Like a recipe \u2014 same ingredients can make different dishes."},{id:"fc10",type:"Concept",difficulty:"Easy",front:"What was Raga Deepak associated with?",back:"Raga Deepak was associated with fire and heat. Legend says that when Tansen sang it, lamps lit on their own \u2014 but the heat was so intense it endangered his own life.",memory_hook:"Deepak = lamp/light. Deepak raga = fire. Too hot even for the singer!"},{id:"fc11",type:"Concept",difficulty:"Easy",front:"What was Raga Megh Malhar associated with?",back:"Raga Megh Malhar was associated with rain and cooling. Legend says that singing it would bring rain. Tansen's wife Hussaini sang it to save him from the dangerous heat of Raga Deepak.",memory_hook:"Megh = cloud/rain. Malhar = rain raga. Cooling, life-saving \u2014 the opposite of Deepak."},{id:"fc12",type:"Why/How",difficulty:"Easy",front:"How did Tansen's wife Hussaini save his life?",back:"When Tansen sang Raga Deepak and his body began to overheat dangerously, Hussaini sang Raga Megh Malhar \u2014 the rain raga \u2014 to cool him down and save his life.",memory_hook:"Fire (Deepak) vs Water (Megh). Hussaini = hero of the raga battle."},{id:"fc13",type:"Definition",difficulty:"Easy",front:"What is 'riyaaz'?",back:"Riyaaz is the regular, disciplined daily practice of music (or any skill). It is the consistent hard work that builds mastery over time.",memory_hook:"Riyaaz = daily grind. Tansen did riyaaz for 11 years. No great musician skips practice."},{id:"fc14",type:"Application",difficulty:"Easy",front:"What is the moral of the story 'Tansen'?",back:"Natural talent + dedicated practice (riyaaz) + learning from great teachers (guru-shishya tradition) = true mastery. Greatness is earned through consistent hard work, not just born.",memory_hook:"Talent alone \u2260 greatness. Talent + Practice + Guru = Tansen."},{id:"fc15",type:"Why/How",difficulty:"Easy",front:"Why is Tansen considered one of India's greatest musicians?",back:"Because he combined extraordinary natural talent with eleven years of training under Swami Haridas, further training under Muhammad Ghaus, and lifelong dedication. His music was said to have supernatural powers. He was honoured by Emperor Akbar himself as one of the Navaratnas.",memory_hook:"Natural gift + 11 year training + royal recognition = India's musical legend."},{id:"fc16",type:"Concept",difficulty:"Easy",front:"What is the guru-shishya tradition?",back:"A traditional Indian system of education where a guru (teacher/master) personally trains a shishya (student/disciple), often living together. The student serves and respects the guru while receiving deep, personalised knowledge.",memory_hook:"Guru = master teacher. Shishya = devoted student. Together = extraordinary learning."},{id:"fc17",type:"Recall",difficulty:"Easy",front:"What was Tansen doing in the forest when Swami Haridas found him?",back:"He was imitating the sounds of animals and birds \u2014 roaring like a tiger, calling like birds. His voice and musical ability were extraordinary, even untrained.",memory_hook:"Wild boy + animal sounds + curious guru = the beginning of a legend."},{id:"fc18",type:"Application",difficulty:"Easy",front:"How does Tansen's story connect to Karnataka's classical music tradition?",back:"Karnataka has the Carnatic music tradition. Purandaradasa, called the Father of Carnatic Music, lived in Karnataka and trained countless students \u2014 just like Swami Haridas trained Tansen. Both traditions value the guru-shishya relationship, daily riyaaz, and deep knowledge of ragas.",memory_hook:"Tansen = Hindustani. Purandaradasa = Carnatic. Both = guru-shishya + riyaaz + ragas."},{id:"fc19",type:"Why/How",difficulty:"Easy",front:"Why is Swami Haridas important in Tansen's life?",back:"Swami Haridas was the most influential person in Tansen's musical development. He recognised raw talent, took Tansen as a student, and patiently trained him for eleven years. Without Swami Haridas, Tansen's gift might never have been fully developed.",memory_hook:"Talent without a teacher = uncut diamond. Swami Haridas was Tansen's cutter."},{id:"fc20",type:"Application",difficulty:"Easy",front:"What three lessons from Tansen's life can you apply to your own studies or hobby?",back:"1. Find a good teacher \u2014 like Swami Haridas, a great guide makes all the difference. 2. Practice daily \u2014 Tansen did riyaaz for eleven years. Regular effort beats occasional bursts. 3. Stay humble \u2014 Tansen remained a student even as his fame grew. Humility is essential to continued learning.",memory_hook:"Good teacher + daily practice + humility = your own version of Tansen's success."}]}},2943,[]);